{
  "root_causes": [
    {
      "service": "ts-route-service",
      "fault_kind": "network_delay",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT attr_source, attr_destination, round(sum(CASE WHEN src='a' THEN sum END)/nullif(sum(CASE WHEN src='a' THEN count END),0),4) abn_mean_s, round(sum(CASE WHEN src='n' THEN sum END)/nullif(sum(CASE WHEN src='n' THEN count END),0),4) norm_mean_s FROM (SELECT 'a' src,* FROM abnormal_metrics_histogram UNION ALL SELECT 'n',* FROM normal_metrics_histogram) WHERE metric='hubble_http_request_duration_seconds' AND attr_destination LIKE '%route-service%' AND attr_source IS NOT NULL GROUP BY ALL ORDER BY 1,2",
          "claim": "Mean hubble request duration to ts-route-service rose about 3x only from ts-ui-dashboard (0.034s to 0.106s); other callers unchanged."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_source, attr_destination, count, round(sum,3) sum_s, round(min,4) min_s, round(max,4) max_s FROM abnormal_metrics_histogram WHERE metric='hubble_http_request_duration_seconds' AND attr_source LIKE '%ui-dash%' AND attr_destination LIKE '%route-service%' LIMIT 30",
          "claim": "Per-interval hubble latency sums on the ui-dashboard to route-service connection are bursty, with large spikes in some intervals."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind kind, attr_http_response_status_code code, count(*) n, round(avg(duration)/1e6,1) avg_ms, round(max(duration)/1e6,1) max_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name='GET /api/v1/routeservice/routes' GROUP BY ALL",
          "claim": "ts-ui-dashboard GET /api/v1/routeservice/routes returned 503 in 118 of 141 spans, averaging about 3.1 s, versus 32 ms normally."
        },
        {
          "kind": "trace",
          "sql": "SELECT attr_k8s_pod_name pod, span_name, attr_span_kind kind, attr_http_response_status_code code, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='ts-route-service' GROUP BY ALL",
          "claim": "ts-route-service's own server spans stay fast (about 5-10 ms, all 200), so the slowness sits outside the service, on the connection."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-route-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_http_response_status_code code, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name='GET /api/v1/routeservice/routes' GROUP BY ALL",
          "claim": "Dashboard /routes requests fail with 503 after about 3.5 s; the slow link to route-service surfaces as user-facing 503s."
        }
      ]
    }
  ]
}
